type OrgSettings = {
  name: string;
  timezone: string;
  notifyEmail: boolean;
  notifySlack: boolean;
  retentionDays: number;
};

import { createResource } from 'qortex-resource';

export function createSettingsResource(orgId: string) {
  return createResource<OrgSettings>({
    key: ['settings', orgId],
    mutation: { optimistic: true },
    persist: { draft: true, debounce: 200 },
    validate: {
      on: 'change',
      fields: {
        name: (v) => (!v?.trim() ? 'Workspace name required' : null),
        retentionDays: (v) =>
          v < 7 || v > 365 ? 'Must be between 7 and 365' : null,
      },
    },
    source: {
      fetch: () => api.orgs.getSettings(orgId),
      save: (draft) => api.orgs.putSettings(orgId, draft),
    },
    onSaveSuccess: () => toast.success('Settings saved'),
    onSaveError: (err) => toast.error(err.message),
  });
}

const settings = createSettingsResource(orgId);

settings.subscribe((snap) => {
  saveBtn.disabled = !snap.isChanged || !snap.isValid || snap.isSaving;
  nameInput.value = snap.draft?.name ?? '';
  emailToggle.checked = !!snap.draft?.notifyEmail;
});

nameInput.oninput = (e) => settings.set('name', e.target.value);
emailToggle.onchange = (e) => settings.set('notifyEmail', e.target.checked);
saveBtn.onclick = () => settings.save();
discardBtn.onclick = () => settings.resetDraft();

import { createResourceHooks } from 'qortex-resource-react';

export const {
  useResource,
  useField,
} = createResourceHooks((orgId: string) => ({
  key: ['settings', orgId],
  mutation: { optimistic: true },
  persist: { draft: true },
  source: {
    fetch: () => api.orgs.getSettings(orgId),
    save: (d) => api.orgs.putSettings(orgId, d),
  },
  onSaveError: (e) => toast.error(e.message),
}));

export function SettingsPage({ orgId }: { orgId: string }) {
  const { isLoading, isChanged, isSaving, save, resetDraft } = useResource(orgId);
  if (isLoading) return <Spinner />;

  return (
    <div>
      <h1>Workspace settings</h1>
      <NameField />
      <TimezoneField />
      <NotifyEmailField />
      <RetentionField />
      <div>
        <button disabled={!isChanged || isSaving} onClick={() => save()}>
          {isSaving ? 'Saving…' : 'Save'}
        </button>
        <button type="button" disabled={!isChanged} onClick={resetDraft}>
          Discard
        </button>
      </div>
    </div>
  );
}

function NameField() {
  const { value, error, onChange, onBlur } = useField('name');
  return (
    <label>
      Name
      <input value={value ?? ''} onChange={(e) => onChange(e.target.value)} onBlur={onBlur} />
      {error}
    </label>
  );
}

function NotifyEmailField() {
  const { value, onChange } = useField('notifyEmail');
  return (
    <label>
      <input
        type="checkbox"
        checked={!!value}
        onChange={(e) => onChange(e.target.checked)}
      />
      Email notifications
    </label>
  );
}

function RetentionField() {
  const { value, error, onChange, onBlur } = useField('retentionDays');
  return (
    <label>
      Retention (days)
      <input
        type="number"
        value={value ?? 30}
        onChange={(e) => onChange(Number(e.target.value))}
        onBlur={onBlur}
      />
      {error}
    </label>
  );
}
